// ATOM_12 — fonte: planejar.js (7 etapas, cadência enxuta, 23 cenários)
// ATOM_12 — Planejar ações das regras do funil
const OFF = -3 * 60 * 60000; // America/Sao_Paulo (UTC-3, sem horário de verão)
const PREF = '[Funil] ';
const DIA = 86400000;
// Próximo passo sugerido por etapa quando o negócio fica sem atividade agendada
const PROXIMO_PASSO = {
  6: 'Fazer o primeiro contato e marcar a reunião',
  7: 'Conversar com o lead e combinar o envio do diagnóstico',
  29: 'Finalizar o diagnóstico e mover para Proposta Enviada',
  8: 'Confirmar a reunião de apresentação do diagnóstico',
  9: 'Enviar a proposta com valores',
  28: 'Enviar contrato e cobrança',
  11: 'Iniciar o onboarding do cliente',
};

function montar(rows) {
  const cfg = {};
  for (const r of rows || []) {
    const row = r && r.json ? r.json : r;
    if (!row || !row.chave) continue;
    cfg[String(row.chave).trim()] = row.valor === null || row.valor === undefined ? '' : String(row.valor).trim();
  }
  return cfg;
}
function v(cfg, k, d) {
  const x = cfg[k];
  return x !== undefined && x !== '' && !/^PENDENTE/i.test(x) ? x : d;
}
function parseHorario(s) {
  const partes = String(s).split(';');
  const hs = partes[0].split('-');
  const min = (x) => { const p = x.split(':'); return Number(p[0]) * 60 + Number(p[1] || 0); };
  return { ini: min(hs[0]), fim: min(hs[1]), dias: (partes[1] || '1,2,3,4,5').split(',').map(Number) };
}
// "lms" = milissegundos no relógio local (campos UTC do Date representam a hora local)
const diaSem = (lms) => { const d = new Date(lms).getUTCDay(); return d === 0 ? 7 : d; };
const minDia = (lms) => { const d = new Date(lms); return d.getUTCHours() * 60 + d.getUTCMinutes(); };
const inicioDia = (lms) => { const d = new Date(lms); return Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()); };
function proxInicioUtil(lms, H) {
  for (let i = 0; i < 20; i++) {
    const d0 = inicioDia(lms);
    if (H.dias.includes(diaSem(lms))) {
      const m = minDia(lms);
      if (m < H.ini) return d0 + H.ini * 60000;
      if (m < H.fim) return lms;
    }
    lms = d0 + DIA;
  }
  return lms;
}
function somarHorasUteis(lms, horas, H) {
  let cur = proxInicioUtil(lms, H);
  let rest = horas * 60;
  for (let i = 0; i < 60 && rest > 0; i++) {
    const fimDia = inicioDia(cur) + H.fim * 60000;
    const disp = (fimDia - cur) / 60000;
    if (disp >= rest) return cur + rest * 60000;
    rest -= disp;
    cur = proxInicioUtil(fimDia, H);
  }
  return cur;
}
function proxDiaUtil(lms, H) {
  let d = inicioDia(lms);
  for (let i = 0; i < 20; i++) { if (H.dias.includes(diaSem(d))) return d; d += DIA; }
  return d;
}
const dataStr = (ms) => new Date(ms).toISOString().slice(0, 10);
const horaStr = (ms) => new Date(ms).toISOString().slice(11, 16);
const iso = (ms) => new Date(ms).toISOString();
const fmtLocal = (lms) => { const s = new Date(lms).toISOString(); return s.slice(8, 10) + '/' + s.slice(5, 7) + ' ' + s.slice(11, 16); };
const parseData = (s) => {
  if (!s) return NaN;
  const t = String(s).trim();
  return Date.parse(/[zZ]|[+-]\d\d:?\d\d$/.test(t) ? t : t.replace(' ', 'T') + 'Z');
};

function planejar(entrada) {
  const cfg = montar(entrada.config);
  const H = parseHorario(v(cfg, 'HORARIO_COMERCIAL', '09:00-18:00;1,2,3,4,5'));
  const ativo = v(cfg, 'FUNIL_REGRAS_ATIVAS', 'false') === 'true';
  const pipeline = Number(v(cfg, 'FUNIL_PIPELINE_ID', '2'));
  const S_NOVO = Number(v(cfg, 'FUNIL_STAGE_NOVO_ID', '6'));
  const S_PROP = Number(v(cfg, 'FUNIL_STAGE_PROPOSTA_ENVIADA_ID', '8'));
  const S_REUN = Number(v(cfg, 'FUNIL_STAGE_REUNIAO_CONCLUIDA_ID', '9'));
  const slaH = Number(v(cfg, 'FUNIL_SLA_PROPOSTA_HORAS', '2')) || 2;
  const lista = (k, d) => v(cfg, k, d).split(',').map((s) => Number(s.trim())).filter((n) => n > 0);
  const fups = lista('FUNIL_DIAG_FUP_DIAS', '3,7');
  const abordagemDias = lista('FUNIL_ABORDAGEM_DIAS', '3,7');
  const alertaUser = Number(v(cfg, 'PD_ALERTA_USER_ID', '0')) || null;
  const campoLink = v(cfg, 'PD_DEAL_PROPOSTA_LINK', '');
  const campoServico = v(cfg, 'PD_DEAL_SERVICO', '');
  const travaEtapas = v(cfg, 'FUNIL_TRAVA_ETAPAS', '28,11').split(',').map((s) => Number(s.trim())).filter(Boolean);
  const S_ACEITA = Number(v(cfg, 'PD_STAGE_PROPOSTA_ACEITA_ID', '28'));
  const S_CONTRATO = Number(v(cfg, 'FUNIL_STAGE_CONTRATO_ID', '11'));
  const fupsProp = lista('FUNIL_PROP_FUP_DIAS', '2,7');
  const S_DIAG = Number(v(cfg, 'FUNIL_STAGE_DIAGNOSTICO_ID', '29'));
  const slaDiagH = Number(v(cfg, 'FUNIL_SLA_DIAGNOSTICO_HORAS', '4')) || 4;
  const lembreteEtapas = v(cfg, 'FUNIL_LEMBRETE_ETAPAS', '6,7,8').split(',').map((s) => Number(s.trim())).filter(Boolean).concat([S_DIAG]);
  // Etapas que disparam mensagem ao cliente quando o card entra (Contactado não: o vendedor já está conversando)
  const msgEtapas = v(cfg, 'FUNIL_MSG_ETAPAS', '29,8,9,28,11').split(',').map((s) => Number(s.trim())).filter(Boolean);

  const now = entrada.agora;
  const nowL = now + OFF;

  // Segurança: se a leitura do Pipedrive falhou, não faz nada (evita apagar tarefas por engano)
  const paginas = (entrada.negocios || []).map((i) => (i && i.json ? i.json : i));
  if (!paginas.length || paginas.some((p) => !p || p.success !== true)) throw new Error('Leitura de negócios do Pipedrive falhou — nada foi alterado.');
  const pagAtv = (entrada.atividades || []).map((i) => (i && i.json ? i.json : i));
  if (!pagAtv.length || pagAtv.some((p) => !p || p.success !== true)) throw new Error('Leitura de atividades do Pipedrive falhou — nada foi alterado.');

  const deals = [].concat(...paginas.map((p) => p.data || [])).filter((d) => Number(d.pipeline_id) === pipeline && d.status === 'open');
  const acts = [].concat(...pagAtv.map((p) => p.data || [])).filter((a) => !a.done);
  const estadoRows = (entrada.estado || []).map((i) => (i && i.json ? i.json : i)).filter((r) => r && r.deal_id);
  const estado = {};
  for (const r of estadoRows) estado[String(r.deal_id)] = r;
  const baselineFeita = !!estado.__linha_base__;

  const out = [];
  const criados = new Set();
  const atvs = (dealId, prefixo) => acts.filter((a) => String(a.deal_id) === String(dealId) && typeof a.subject === 'string' && a.subject.startsWith(PREF + prefixo));
  const criar = (body) => {
    const ja = acts.some((a) => String(a.deal_id || '') === String(body.deal_id || '') && a.subject === body.subject);
    const chave = body.deal_id + '|' + body.subject;
    if (ja || criados.has(chave)) return;
    criados.add(chave);
    out.push({ tipo: 'criar_atividade', body });
  };
  const concluir = (id) => out.push({ tipo: 'concluir_atividade', id: String(id) });
  const excluir = (id) => out.push({ tipo: 'excluir_atividade', id: String(id) });
  const salvar = (row) => out.push({ tipo: 'estado', row: {
    deal_id: String(row.deal_id), stage_id: Number(row.stage_id), entrou_etapa_em: row.entrou_etapa_em,
    alerta_atender: !!row.alerta_atender, alerta_proposta: !!row.alerta_proposta, agendados: row.agendados || '', atualizado_em: iso(now) } });
  const temChave = (st, k) => String(st.agendados || '').split(';').includes(k);
  const addChave = (st, k) => { st.agendados = (st.agendados ? st.agendados + ';' : '') + k; };
  // Ao mudar de etapa, só os lembretes de reunião (chaves R:) continuam valendo
  const manterLembretes = (ag) => String(ag || '').split(';').filter((k) => k.startsWith('R:')).join(';');
  const remover = (dealId) => out.push({ tipo: 'estado_remover', deal_id: String(dealId) });
  const alerta = (d, titulo, texto) => criar({
    subject: PREF + '⚠️ ' + titulo + ' — ' + d.title,
    type: 'task',
    owner_id: alertaUser || d.owner_id,
    deal_id: d.id,
    due_date: dataStr(nowL),
    note: texto,
  });
  // Variação determinística de minutos para as mensagens não saírem sempre no mesmo horário
  const jitter = (id, salt, max) => { let h = 7; const s = String(id) + ':' + String(salt); for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) % 100003; return h % max; };
  const roteiro = (tipo, padrao) => v(cfg, 'FUNIL_ROTEIRO_' + tipo, v(cfg, 'FUNIL_OBJ_' + tipo, padrao || ''));
  const agendarMsg = (d, etapa, tipoMsg, objetivo, quandoUtc, ref) => out.push({ tipo: 'mensagem', row: {
    deal_id: String(d.id), deal_titulo: d.title || '', person_id: d.person_id ? String(d.person_id) : '', stage_id: etapa,
    etapa: String(etapa), tipo_msg: tipoMsg, objetivo: objetivo || roteiro(tipoMsg), agendado_para: iso(quandoUtc), texto: '', status: 'AGENDADA',
    criado_em: iso(now), erro: '', ref: ref || '' } });
  // Horário "humano" num dia útil: início do expediente + minutos variados
  const noDiaUtil = (lmsDia, d, salt, minIni, faixa) => proxDiaUtil(lmsDia, H) + H.ini * 60000 + (minIni + jitter(d.id, salt, faixa)) * 60000;
  const somarDiasUteis = (lms, n) => { let x = inicioDia(lms); let c = 0; while (c < n) { x += DIA; if (H.dias.includes(diaSem(x))) c++; } return x; };
  const lerCampo = (d, id) => {
    if (!id) return '';
    const cf = d.custom_fields || {};
    let x = cf[id] !== undefined ? cf[id] : d[id];
    if (x && typeof x === 'object' && 'value' in x) x = x.value;
    return x === null || x === undefined ? '' : String(x).trim();
  };

  // Primeira execução: só registra onde cada negócio está, sem criar nada
  if (!baselineFeita) {
    for (const d of deals) salvar({ deal_id: d.id, stage_id: d.stage_id, entrou_etapa_em: iso(parseData(d.stage_change_time || d.add_time) || now) });
    salvar({ deal_id: '__linha_base__', stage_id: 0, entrou_etapa_em: iso(now) });
    return out;
  }

  const saida = (dealId, etapa) => {
    if (etapa === S_NOVO) atvs(dealId, 'Atender lead').forEach((a) => concluir(a.id));
    if (etapa === S_PROP) atvs(dealId, 'Follow-up').forEach((a) => excluir(a.id));
    if (etapa === S_REUN) atvs(dealId, 'Enviar proposta').forEach((a) => concluir(a.id));
    if (etapa === S_DIAG) atvs(dealId, 'Preparar diagnóstico').forEach((a) => concluir(a.id));
  };

  const entradaEtapa = (d, etapa, entradaMs, etapaAnterior) => {
    const entL = entradaMs + OFF;
    if (etapa === S_NOVO) {
      let ini = proxInicioUtil(entL, H);
      const fimDia = inicioDia(ini) + H.fim * 60000;
      if (fimDia - ini < 60 * 60000) ini = proxInicioUtil(fimDia, H); // menos de 1h útil no dia: vence no próximo dia útil
      criar({ subject: PREF + 'Atender lead — ' + d.title, type: 'task', owner_id: d.owner_id, deal_id: d.id, due_date: dataStr(ini),
        note: v(cfg, 'FUNIL_ROTEIRO_TAREFA_ATENDER', 'Regra do funil: todo lead deve ser atendido no mesmo dia útil em que entra (normalmente já marcando a reunião).') });
      // Abordagem da prospecção: no dia e mais 2 tentativas em dias úteis (para quando o card sai da etapa)
      const b0 = proxInicioUtil(Math.max(nowL, entL), H);
      const q0 = b0 === Math.max(nowL, entL) ? b0 + (5 + jitter(d.id, 'a0', 25)) * 60000 : b0 + (20 + jitter(d.id, 'a0', 60)) * 60000;
      agendarMsg(d, etapa, 'ABORDAGEM_1', null, q0 - OFF);
      abordagemDias.forEach((n, i) => {
        agendarMsg(d, etapa, 'ABORDAGEM_' + (i + 2), null, noDiaUtil(somarDiasUteis(entL, n), d, 'a' + (i + 1), 30, 120) - OFF);
      });
    }
    if (etapa === S_REUN) {
      const limUtc = somarHorasUteis(entL, slaH, H) - OFF;
      criar({ subject: PREF + 'Enviar proposta — ' + d.title, type: 'task', owner_id: d.owner_id, deal_id: d.id, due_date: dataStr(limUtc), due_time: horaStr(limUtc),
        note: v(cfg, 'FUNIL_ROTEIRO_TAREFA_PROPOSTA', 'Regra do funil: proposta com valores enviada em até ' + slaH + 'h úteis após a reunião. Ao enviar, preencha o campo "Link da proposta" no negócio.') });
    }
    // Diagnóstico (interno): tarefa para montar o mapa do cliente dentro do prazo
    if (etapa === S_DIAG) {
      const limUtc = somarHorasUteis(entL, slaDiagH, H) - OFF;
      criar({ subject: PREF + 'Preparar diagnóstico — ' + d.title, type: 'task', owner_id: d.owner_id, deal_id: d.id, due_date: dataStr(limUtc), due_time: horaStr(limUtc),
        note: v(cfg, 'FUNIL_ROTEIRO_TAREFA_DIAGNOSTICO', 'Monte o diagnóstico (SEO, GEO, site, SEO local e atendimento) em até ' + slaDiagH + 'h úteis. Ao enviar, mova o card para Proposta Enviada.') });
    }
    // Follow-ups do diagnóstico (cancelados pelo ATOM_13 se houver reunião agendada)
    if (etapa === S_PROP) {
      fups.forEach((n, i) => {
        const quandoL = noDiaUtil(somarDiasUteis(entL, n), d, 'f' + i, 30, 150); // entre ~9h30 e ~12h
        agendarMsg(d, etapa, 'DIAG_FUP_' + (i + 1), null, quandoL - OFF);
      });
    }
    // Proposta aceita: lembrete de assinatura em 2 dias úteis (cancelado se o card avançar)
    if (etapa === S_ACEITA) {
      agendarMsg(d, etapa, 'LEMBRETE_ASSINATURA', null, noDiaUtil(somarDiasUteis(entL, 2), d, 'la', 45, 120) - OFF);
    }
    // Contrato assinado: pedido de indicação em 30 dias (continuam mesmo com o negócio ganho)
    if (etapa === S_CONTRATO) {
      agendarMsg(d, etapa, 'POS_INDICACAO_30', null, noDiaUtil(entL + 30 * DIA, d, 'p30', 60, 120) - OFF);
    }
    if (etapaAnterior !== null && msgEtapas.includes(etapa)) {
      const objetivo = roteiro('ETAPA_' + etapa, v(cfg, 'FUNIL_MSG_ETAPA_' + etapa, ''));
      if (objetivo) {
        const base = proxInicioUtil(Math.max(nowL, entL), H);
        const quandoL = base === Math.max(nowL, entL) ? base + (3 + jitter(d.id, etapa, 12)) * 60000 : base + (10 + jitter(d.id, etapa, 50)) * 60000;
        agendarMsg(d, etapa, 'ETAPA_' + etapa, objetivo, quandoL - OFF);
      }
    }
  };

  // Proposta enviada (link preenchido): mensagem com a proposta + follow-ups em dias úteis
  const cadenciaProposta = (d, st) => {
    const base = proxInicioUtil(nowL, H);
    const quandoL = base === nowL ? base + (4 + jitter(d.id, 'pe', 10)) * 60000 : base + (10 + jitter(d.id, 'pe', 40)) * 60000;
    agendarMsg(d, S_REUN, 'PROPOSTA_ENVIADA', null, quandoL - OFF);
    fupsProp.forEach((n, i) => {
      agendarMsg(d, S_REUN, 'PROP_FUP_' + (i + 1), null, noDiaUtil(somarDiasUteis(nowL, n), d, 'fp' + i, 30, 150) - OFF);
    });
    addChave(st, 'P');
  };

  // Reuniões agendadas (atividade tipo Reunião com data e hora): lembrete na véspera
  const lembretesReuniao = (d, st) => {
    const reunioes = acts.filter((a) => String(a.deal_id) === String(d.id) && a.type === 'meeting' && a.due_date && a.due_time);
    let mudou = false;
    for (const a of reunioes) {
      const hora = String(a.due_time).slice(0, 5);
      const quando = Date.parse(a.due_date + 'T' + hora + ':00Z'); // Pipedrive guarda hora em UTC
      if (!(quando > now)) continue;
      const chave = 'R:' + a.id + '|' + a.due_date + '|' + hora;
      if (temChave(st, chave)) continue;
      const ref = a.id + '|' + a.due_date + '|' + hora;
      const qL = quando + OFF;
      // Véspera: último dia útil antes da reunião, entre 16h e 17h
      let vesp = inicioDia(qL) - DIA;
      for (let i = 0; i < 7 && !H.dias.includes(diaSem(vesp)); i++) vesp -= DIA;
      const vespL = vesp + 16 * 60 * 60000 + jitter(d.id, 'v' + a.id, 50) * 60000;
      if (qL - nowL > 20 * 3600000 && vespL > nowL) agendarMsg(d, Number(d.stage_id), 'LEMBRETE_VESPERA', null, vespL - OFF, ref);
      addChave(st, chave);
      mudou = true;
    }
    return mudou;
  };

  const vistos = new Set();
  for (const d of deals) {
    const id = String(d.id);
    vistos.add(id);
    const prev = estado[id];
    const etapa = Number(d.stage_id);
    const entradaMs = parseData(d.stage_change_time || d.add_time) || now;
    let st;
    let alterado = false;

    if (!prev) {
      st = { deal_id: id, stage_id: etapa, entrou_etapa_em: iso(entradaMs), agendados: '' };
      if (ativo) entradaEtapa(d, etapa, entradaMs, null);
      alterado = true;
    } else if (Number(prev.stage_id) !== etapa) {
      // Trava: não deixa avançar para as etapas protegidas sem valor e serviço preenchidos
      if (ativo && travaEtapas.includes(etapa) && Number(prev.stage_id) > 0) {
        const falta = [];
        if (!(Number(d.value) > 0)) falta.push('Valor');
        if (campoServico && !lerCampo(d, campoServico)) falta.push('Serviço');
        if (falta.length) {
          out.push({ tipo: 'mover', deal_id: id, stage_id: Number(prev.stage_id) });
          alerta(d, 'Card devolvido: falta ' + falta.join(' e '), 'O card "' + d.title + '" foi movido para uma etapa que exige ' + falta.join(' e ') + ' preenchido(s) e voltou automaticamente para a etapa anterior. Preencha ' + falta.join(' e ') + ' no negócio e mova o card de novo.');
          continue;
        }
      }
      st = { deal_id: id, stage_id: etapa, entrou_etapa_em: iso(entradaMs), agendados: manterLembretes(prev.agendados) };
      if (ativo) { saida(id, Number(prev.stage_id)); entradaEtapa(d, etapa, entradaMs, Number(prev.stage_id)); }
      alterado = true;
    } else {
      st = Object.assign({}, prev);
      if (!ativo) continue;
      const entPrevL = (parseData(prev.entrou_etapa_em) || entradaMs) + OFF;
      if (etapa === S_NOVO && !prev.alerta_atender) {
        const pend = atvs(id, 'Atender lead');
        if (pend.length && pend[0].due_date) {
          const limiteL = Date.parse(pend[0].due_date + 'T00:00:00Z') + H.fim * 60000;
          if (nowL > limiteL) {
            alerta(d, 'Lead não atendido no prazo', 'O lead "' + d.title + '" entrou no funil em ' + fmtLocal(entPrevL) + ' e a tarefa "Atender lead" continua aberta. Regra: atender no mesmo dia útil.');
            st.alerta_atender = true;
            alterado = true;
          }
        }
      }
      if (etapa === S_REUN) {
        const link = lerCampo(d, campoLink);
        if (link) {
          atvs(id, 'Enviar proposta').forEach((a) => concluir(a.id));
        } else if (!prev.alerta_proposta) {
          const limiteL = somarHorasUteis(entPrevL, slaH, H);
          if (nowL > limiteL) {
            alerta(d, 'Proposta fora do prazo', 'A reunião com "' + d.title + '" foi concluída em ' + fmtLocal(entPrevL) + ' e o campo "Link da proposta" continua vazio. Regra: proposta em até ' + slaH + 'h úteis.');
            st.alerta_proposta = true;
            alterado = true;
          }
        }
      }
    }

    if (ativo) {
      if (etapa === S_REUN && lerCampo(d, campoLink) && !temChave(st, 'P')) { cadenciaProposta(d, st); alterado = true; }
      if (lembreteEtapas.includes(etapa) && lembretesReuniao(d, st)) alterado = true;
    }
    if (alterado) salvar(st);
  }

  // Regra: todo negócio aberto SEMPRE tem uma atividade pendente agendada
  if (ativo) {
    const fechadas = new Set(out.filter((o) => o.tipo === 'concluir_atividade' || o.tipo === 'excluir_atividade').map((o) => o.id));
    const hojeL = dataStr(nowL);
    for (const d of deals) {
      const pendentes = acts.filter((a) => String(a.deal_id) === String(d.id) && !fechadas.has(String(a.id)));
      const novas = out.filter((o) => o.tipo === 'criar_atividade' && String(o.body.deal_id) === String(d.id));
      if (pendentes.length || novas.length) continue;
      const passo = PROXIMO_PASSO[Number(d.stage_id)] || 'Definir e executar o próximo passo com o cliente';
      criar({ subject: PREF + 'Próximo passo: ' + passo + ' — ' + d.title, type: 'task', owner_id: d.owner_id, deal_id: d.id, due_date: hojeL,
        note: 'Regra do funil: todo negócio aberto precisa ter sempre uma atividade agendada. Execute hoje, registre o que aconteceu e agende a próxima.' });
    }
    // Atividades do funil não executadas no dia: um resumo diário para o gestor (a partir das 9h)
    if (minDia(nowL) >= H.ini) {
      const idsFunil = new Set(deals.map((d) => String(d.id)));
      const atrasadas = acts.filter((a) => a.deal_id && idsFunil.has(String(a.deal_id)) && a.due_date && a.due_date < hojeL && !fechadas.has(String(a.id)));
      if (atrasadas.length) {
        const titulo = (id) => (deals.find((d) => String(d.id) === String(id)) || {}).title || id;
        criar({ subject: PREF + '⚠️ Atividades atrasadas no funil — ' + fmtLocal(nowL).slice(0, 5), type: 'task', owner_id: alertaUser || deals[0].owner_id, due_date: hojeL,
          note: 'Regra: todas as atividades devem ser executadas no dia. Pendentes de dias anteriores (' + atrasadas.length + '):<br>' +
            atrasadas.slice(0, 40).map((a) => '• ' + titulo(a.deal_id) + ' — ' + a.subject + ' (venceu ' + a.due_date.slice(8, 10) + '/' + a.due_date.slice(5, 7) + ')').join('<br>') });
      }
    }
  }

  // Negócios que saíram do funil aberto (ganhos, perdidos, excluídos ou movidos de funil)
  for (const r of estadoRows) {
    const id = String(r.deal_id);
    if (id === '__linha_base__' || vistos.has(id)) continue;
    if (ativo) atvs(id, '').filter((a) => !a.subject.startsWith(PREF + '⚠️')).forEach((a) => excluir(a.id));
    remover(id);
  }
  return out;
}

